function readTopUp(body: string) {
  const data = JSON.parse(body);
  return { walletId: data.walletId, amount: data.amount };
}

console.log(readTopUp('{"walletId": "W1", "amount": "500"}'));

questions.expected:
{ walletId: 'W1', amount: 500 }
bad amount
not an object

questions.solution:
interface TopUp {
  walletId: string;
  amount: number;
}

function readTopUp(body: string): TopUp | string {
  const data: unknown = JSON.parse(body);
  if (typeof data !== "object" || data === null) return "not an object";
  if (!("walletId" in data) || typeof data.walletId !== "string") return "bad walletId";
  if (!("amount" in data) || typeof data.amount !== "number" || !Number.isInteger(data.amount) || data.amount <= 0) {
    return "bad amount";
  }
  return { walletId: data.walletId, amount: data.amount };
}

console.log(readTopUp('{"walletId": "W1", "amount": 500}'));
console.log(readTopUp('{"walletId": "W1", "amount": "500"}'));
console.log(readTopUp("42"));

