const limits = new Map([["gold", 50000]]);

function fail(message: string): never {
  throw new Error(message);
}

function limitFor(tier: string): number {
  const limit = limits.get(tier);
  if (limit === undefined) fail(`no limit for tier ${tier}`);
  return limit;
}

console.log(limitFor("gold") * 2);
try {
  limitFor("platinum");
} catch (error) {
  console.log((error as Error).message);
}

